<main class="write-main ux-workflow"><header class="ux-page-heading"><p class="ux-eyebrow">Publishing desk</p><h1>Suitability first. Repeats by agreement.</h1><p><?=e($r['fields']['title'])?></p><a class="wbtn" href="<?=url('/write/desk/'.$r['id'])?>">Back to article, quote and creative controls</a></header><?php if($error):?><p class="notice error" role="alert"><?=e($error)?></p><?php endif;?>
<section class="settings-card"><h2>1. Advertising suitability</h2><p><?=e(commercial_policy())?></p><p><strong>Saved review:</strong> <?=e($r['suitability']['state']??'Existing editorial workflow')?>. <?=commercial_suitable($r,$post)?'Current suitability gate satisfied.':'A current review is required.'?></p><details><summary>Read the current article and public claims</summary><h3><?=e($post['title'])?></h3><p><?=e($post['standfirst'])?></p><div class="article-body"><?=sanitize_html($post['content_html'])?></div><p>Customer destination: <?=e($r['fields']['purchase_url']?:$r['fields']['apply_url'])?></p></details>
