<?php endif;?></section>
<?php if($order&&!empty($order['automatic_repeats'])):?><section class="settings-card"><h2>3. First round and repeat status</h2><p><strong><?=e(ucfirst($order['automatic_repeats']['state']))?></strong> · <?=e($order['automatic_repeats']['notice'])?></p><p>Future delivery stops when payment, suitability, source, approvals, contract, destination or offer validity changes. Missed or uncertain posts require review, not a catch-up burst.</p><form method="post"><?=csrf_field()?><input type="hidden" name="order" value="<?=e($order['id'])?>"><?php if(!empty($order['automatic_repeats']['enabled'])):?><button class="wbtn primary" name="action" value="launch">Launch first approved round on its agreed date</button><button class="wbtn" name="action" value="pause">Pause automatic repeats</button><?php endif;?></form><a href="<?=url('/write/desk/'.$r['id'].'#client-results')?>">Review actual delivery evidence</a></section><?php endif;?></main>
